import * as THREE from "three";

import {
  applyBonePose,
  applyEmoteToRig,
  applyRuntimeAnimation,
  createSteveRig,
  disposeLoadedCosmetic,
  disposeLoadedEmote,
  EmotePlayer,
  inferModelVariant,
  loadCosmetic,
  loadEmote,
  loadSkinTexture,
  mountCosmeticOnRig,
  createNametag,
  CAMERA_FOV,
  CAMERA_POSITION,
  DOWN_SHIFT,
  IDLE_POSE,
  LIGHTING,
  NAMETAG_HAT_EXTRA_Y,
  NAMETAG_LAYER,
  NAMETAG_PX_Y,
  POSE_ROTATION_Y,
  RIG_RENDERER_SETTINGS,
  STEVE_CENTER_PX,
  STEVE_WORLD_SCALE,
  type BonePose,
  type CosmeticAssetUrls,
  type EmoteAssetUrls,
  type LoadedCosmetic,
  type LoadedEmote,
  type NametagHandle,
  type NametagOptions,
  type SteveModelVariant,
  type SteveRig,
  assertWebGLAvailable,
  RIG_CONTEXT_ATTRIBUTES,
} from "../core";
import {
  applyOutlineConfig,
  renderOutlineFrame,
  setupOutlinePipeline,
  type OutlinePipeline,
  type PromoOutlineConfig,
} from "../postfx/promoOutline";

export type SnapshotView = "front" | "back" | "left" | "right";

export interface SnapshotCape {
  texture: string;
  mcmeta?: string;
  mcmetaJson?: unknown;
  elytra?: boolean;
}

export interface SnapshotCosmetic {
  id: string;
  type?: string;
  urls: CosmeticAssetUrls;
}

export interface SkinSnapshotRequest {
  textureUrl: string;
  variant?: SteveModelVariant | "auto";
  cosmetics?: SnapshotCosmetic[];
  cape?: string | SnapshotCape | null;
  emote?: EmoteAssetUrls | null;
  emoteTime?: number;
  bones?: Record<string, BonePose> | null;
  nametag?: NametagOptions | null;
  view?: SnapshotView;
  rotation?: number;
  body?: boolean;
  fit?: boolean | number;
  crop?: boolean | number;
  fov?: number;
  focus?: number;
  outline?: boolean | Partial<PromoOutlineConfig>;
}

export interface SkinSnapshotOptions {
  mimeType?: string;
  quality?: number;
}

const VIEW_ROTATION: Record<SnapshotView, number> = {
  front: 0,
  back: Math.PI,
  left: Math.PI / 2,
  right: -Math.PI / 2,
};

const FIT_MARGIN = 1.12;
const ALPHA_CUTOFF = 16;
const CROP_PADDING = 0.02;

interface ContentBounds {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
  width: number;
  height: number;
}

function capeCosmetic(cape: string | SnapshotCape): SnapshotCosmetic {
  const asset = typeof cape === "string" ? { texture: cape } : cape;
  const type = asset.elytra ? "ELYTRA" : "CAPE";
  return {
    id: type.toLowerCase(),
    type,
    urls: {
      geo: "",
      texture: asset.texture,
      mcmeta: asset.mcmeta,
      mcmetaJson: asset.mcmetaJson,
      metadataJson: { type },
    },
  };
}

function cosmeticEntries(request: SkinSnapshotRequest): SnapshotCosmetic[] {
  const entries = [...(request.cosmetics ?? [])];
  if (request.cape) entries.push(capeCosmetic(request.cape));
  return entries;
}

function resolveBones(
  request: SkinSnapshotRequest
): Record<string, BonePose> | null {
  if (request.bones !== undefined) return request.bones;
  return request.emote ? null : IDLE_POSE;
}

function nametagY(request: SkinSnapshotRequest): number {
  const hat = (request.cosmetics ?? []).some(
    (c) => c.type?.toUpperCase() === "HAT"
  );
  return hat ? NAMETAG_PX_Y + NAMETAG_HAT_EXTRA_Y : NAMETAG_PX_Y;
}

function hideMeshes(root: THREE.Object3D): void {
  root.traverse((o) => {
    if (o instanceof THREE.Mesh) o.visible = false;
  });
}

class SnapshotStage {
  readonly root = new THREE.Group();
  readonly pose = new THREE.Group();

  private readonly detachers: Array<() => void> = [];
  private readonly cosmetics: LoadedCosmetic[] = [];
  private emote: LoadedEmote | null = null;
  private nametag: NametagHandle | null = null;

  constructor(
    readonly rig: SteveRig,
    readonly variant: SteveModelVariant,
    rotation: number,
    lowered: boolean
  ) {
    this.root.scale.setScalar(STEVE_WORLD_SCALE);
    this.root.position.set(
      0,
      -STEVE_CENTER_PX * STEVE_WORLD_SCALE - (lowered ? DOWN_SHIFT : 0),
      0
    );
    this.pose.rotation.y = rotation;
    this.pose.add(rig.tree.root);
    this.root.add(this.pose);
  }

  addNametag(nametag: NametagHandle, y: number): void {
    this.nametag = nametag;
    nametag.mesh.position.set(0, y, 0);
    this.pose.add(nametag.mesh);
  }

  addCosmetic(cosmetic: LoadedCosmetic): void {
    this.cosmetics.push(cosmetic);

    const detach = mountCosmeticOnRig(cosmetic, this.rig, this.variant);
    this.detachers.push(detach);

    if (!cosmetic.hasArmorBones && cosmetic.particleEffects.length > 0) {
      const object = cosmetic.tree.root;
      this.pose.add(object);
      this.detachers.push(() => this.pose.remove(object));
    }
  }

  addEmote(emote: LoadedEmote): void {
    this.emote = emote;
    const prop = emote.prop?.tree.root;
    if (prop) {
      this.pose.add(prop);
      this.detachers.push(() => this.pose.remove(prop));
    }
  }

  dispose(): void {
    for (const detach of this.detachers.reverse()) detach();
    for (const cosmetic of this.cosmetics) disposeLoadedCosmetic(cosmetic);
    if (this.emote) disposeLoadedEmote(this.emote);
    if (this.nametag) {
      this.nametag.mesh.removeFromParent();
      this.nametag.dispose();
    }
    this.root.removeFromParent();
    this.rig.dispose();
  }
}

export class SkinSnapshotRenderer {
  private renderer: THREE.WebGLRenderer | null = null;
  private scene: THREE.Scene | null = null;
  private camera: THREE.PerspectiveCamera | null = null;
  private outline: OutlinePipeline | null = null;
  private fitTarget: THREE.Vector3 | null = null;
  private queue: Promise<unknown> = Promise.resolve();

  constructor(
    private readonly width = 360,
    private readonly height = 504
  ) {}

  snapshot(
    request: SkinSnapshotRequest,
    options: SkinSnapshotOptions = {}
  ): Promise<Blob> {
    const run = () => this.renderOne(request, options);
    const result = this.queue.then(run, run);
    this.queue = result.catch(() => undefined);
    return result;
  }

  dispose(): void {
    if (this.outline) {
      this.outline.depthRT.dispose();
      this.outline.composer.dispose();
      this.outline = null;
    }
    this.renderer?.dispose();
    this.renderer = null;
    this.scene = null;
    this.camera = null;
  }

  private init(): void {
    if (this.renderer) return;

    assertWebGLAvailable();

    const canvas = document.createElement("canvas");
    canvas.width = this.width;
    canvas.height = this.height;

    const renderer = new THREE.WebGLRenderer({
      canvas,
      ...RIG_CONTEXT_ATTRIBUTES,
    });
    renderer.outputColorSpace = RIG_RENDERER_SETTINGS.outputColorSpace;
    renderer.toneMapping = RIG_RENDERER_SETTINGS.toneMapping;
    renderer.setPixelRatio(1);
    renderer.setSize(this.width, this.height, false);
    renderer.setClearColor(0x000000, 0);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(
      CAMERA_FOV,
      this.width / this.height,
      0.1,
      1000
    );

    const directional = new THREE.DirectionalLight(
      0xffffff,
      LIGHTING.directional
    );
    directional.position.set(...LIGHTING.directionalPosition);
    scene.add(
      new THREE.AmbientLight(0xffffff, LIGHTING.ambient),
      new THREE.HemisphereLight(
        LIGHTING.hemisphereSky,
        LIGHTING.hemisphereGround,
        LIGHTING.hemisphere
      ),
      directional
    );

    this.renderer = renderer;
    this.scene = scene;
    this.camera = camera;
  }

  private async renderOne(
    request: SkinSnapshotRequest,
    options: SkinSnapshotOptions
  ): Promise<Blob> {
    this.init();

    const stage = await this.buildStage(request);
    this.scene!.add(stage.root);

    try {
      const bones = resolveBones(request);
      if (bones) applyBonePose(stage.rig, bones);

      const fit = request.fit ?? false;
      const overlay = request.nametag ? NAMETAG_LAYER : null;
      this.frameCamera(stage.root, fit, request.fov, request.focus);
      this.renderFrame(request.outline ?? true, overlay);

      if (fit !== false) {
        const slack = this.measureSlack(
          typeof fit === "number" ? fit : FIT_MARGIN
        );
        if (slack !== null) {
          this.pullCamera(slack);
          this.renderFrame(request.outline ?? true, overlay);
        }
      }

      const crop = request.crop ?? false;
      const cropped =
        crop === false
          ? null
          : this.cropToContent(typeof crop === "number" ? crop : CROP_PADDING);

      return await this.toBlob(options, cropped);
    } finally {
      stage.dispose();
    }
  }

  private async buildStage(
    request: SkinSnapshotRequest
  ): Promise<SnapshotStage> {
    const texture = await loadSkinTexture(request.textureUrl);
    const requested = request.variant ?? "auto";
    const variant: SteveModelVariant =
      requested === "auto" ? inferModelVariant(texture.image) : requested;

    const rig = createSteveRig(variant);
    rig.material.map = texture;
    rig.material.needsUpdate = true;
    if (request.body === false) hideMeshes(rig.tree.root);

    const rotation =
      POSE_ROTATION_Y +
      VIEW_ROTATION[request.view ?? "front"] +
      (request.rotation ?? 0);
    const stage = new SnapshotStage(rig, variant, rotation, !!request.nametag);

    try {
      for (const entry of cosmeticEntries(request)) {
        const cosmetic = await this.loadCosmeticAtRest(entry);
        if (cosmetic) stage.addCosmetic(cosmetic);
      }

      if (request.nametag) {
        const nametag = createNametag(request.nametag);
        await nametag.ready;
        stage.addNametag(nametag, nametagY(request));
      }

      if (request.emote) {
        const emote = await this.loadEmoteAtTime(
          request.emote,
          request.emoteTime ?? 0,
          rig
        );
        if (emote) stage.addEmote(emote);
      }
    } catch (err) {
      stage.dispose();
      throw err;
    }

    return stage;
  }

  private async loadCosmeticAtRest(
    entry: SnapshotCosmetic
  ): Promise<LoadedCosmetic | null> {
    let cosmetic: LoadedCosmetic;
    try {
      cosmetic = await loadCosmetic(entry.urls);
    } catch (err) {
      console.warn(`[snapshot] cosmetic ${entry.id} failed to load`, err);
      return null;
    }

    const idle =
      cosmetic.animations.find((a) => a.name === "nrc.idle") ??
      cosmetic.animations[0];
    if (idle) {
      applyRuntimeAnimation(idle, 0, { negateX: cosmetic.config.negateX });
    }

    return cosmetic;
  }

  private async loadEmoteAtTime(
    urls: EmoteAssetUrls,
    time: number,
    rig: SteveRig
  ): Promise<LoadedEmote | null> {
    let emote: LoadedEmote;
    try {
      emote = await loadEmote(urls, { negateX: true });
    } catch (err) {
      console.warn("[snapshot] emote failed to load", err);
      return null;
    }

    const player = new EmotePlayer();
    player.play(emote.emote, 0, { loop: true, fadeInSeconds: 0 });
    player.update(time);
    applyEmoteToRig(player, rig.tree, {
      negateX: true,
      propTree: emote.prop?.tree,
    });

    return emote;
  }

  private frameCamera(
    root: THREE.Object3D,
    fit: boolean | number,
    fov?: number,
    focus?: number
  ): void {
    const camera = this.camera!;

    const nextFov = fov ?? CAMERA_FOV;
    if (camera.fov !== nextFov) {
      camera.fov = nextFov;
      camera.updateProjectionMatrix();
    }

    camera.position.set(...CAMERA_POSITION);
    camera.rotation.set(0, 0, 0);
    camera.updateMatrixWorld(true);

    this.fitTarget = null;
    if (fit === false) return;

    root.updateMatrixWorld(true);
    const box = new THREE.Box3();
    root.traverse((o) => {
      if (o instanceof THREE.Mesh && o.visible) box.expandByObject(o);
    });
    if (box.isEmpty()) return;

    const margin = typeof fit === "number" ? fit : FIT_MARGIN;
    const size = box.getSize(new THREE.Vector3());
    const center = box.getCenter(new THREE.Vector3());
    if (focus !== undefined) center.y = box.min.y + size.y * focus;
    const halfFov = (camera.fov * Math.PI) / 360;

    const tanY = Math.tan(halfFov);
    const tanX = tanY * camera.aspect;
    const vertex = new THREE.Vector3();

    let distance = -Infinity;
    root.traverse((o) => {
      if (!(o instanceof THREE.Mesh) || !o.visible) return;
      const position = o.geometry.getAttribute("position");
      if (!position) return;

      for (let i = 0; i < position.count; i++) {
        vertex.fromBufferAttribute(position, i).applyMatrix4(o.matrixWorld);
        const needed = Math.max(
          vertex.z + Math.abs(vertex.x - center.x) / tanX,
          vertex.z + Math.abs(vertex.y - center.y) / tanY
        );
        if (needed > distance) distance = needed;
      }
    });
    if (!Number.isFinite(distance)) return;

    camera.position.set(
      center.x,
      center.y,
      center.z + (distance - center.z) * margin
    );
    camera.lookAt(center);
    camera.updateMatrixWorld(true);
    this.fitTarget = center.clone();
  }

  private contentBounds(): ContentBounds | null {
    const renderer = this.renderer!;
    const width = renderer.domElement.width;
    const height = renderer.domElement.height;

    const pixels = new Uint8Array(width * height * 4);
    const gl = renderer.getContext();
    gl.readPixels(0, 0, width, height, gl.RGBA, gl.UNSIGNED_BYTE, pixels);

    let minX = width;
    let minY = height;
    let maxX = -1;
    let maxY = -1;

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        if (pixels[(y * width + x) * 4 + 3] <= ALPHA_CUTOFF) continue;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
      }
    }
    if (maxX < minX || maxY < minY) return null;

    return { minX, minY, maxX, maxY, width, height };
  }

  private measureSlack(margin: number): number | null {
    const bounds = this.contentBounds();
    if (!bounds) return null;

    const filled = Math.max(
      (bounds.maxX - bounds.minX + 1) / bounds.width,
      (bounds.maxY - bounds.minY + 1) / bounds.height
    );
    return filled > 0 ? filled * margin : null;
  }

  private cropToContent(padding: number): HTMLCanvasElement | null {
    const bounds = this.contentBounds();
    if (!bounds) return null;

    const contentWidth = bounds.maxX - bounds.minX + 1;
    const contentHeight = bounds.maxY - bounds.minY + 1;
    const padX = Math.round(contentWidth * padding);
    const padY = Math.round(contentHeight * padding);

    const x = Math.max(0, bounds.minX - padX);
    const y = Math.max(0, bounds.height - bounds.maxY - 1 - padY);
    const cropWidth = Math.min(bounds.width - x, contentWidth + padX * 2);
    const cropHeight = Math.min(bounds.height - y, contentHeight + padY * 2);

    const canvas = document.createElement("canvas");
    canvas.width = cropWidth;
    canvas.height = cropHeight;

    const ctx = canvas.getContext("2d");
    if (!ctx) return null;
    ctx.drawImage(
      this.renderer!.domElement,
      x,
      y,
      cropWidth,
      cropHeight,
      0,
      0,
      cropWidth,
      cropHeight
    );
    return canvas;
  }

  private pullCamera(slack: number): void {
    const camera = this.camera!;
    const target = this.fitTarget;
    if (!target) return;

    const distance = camera.position.z - target.z;
    camera.position.z = target.z + distance * slack;
    camera.updateMatrixWorld(true);
  }

  private renderFrame(
    outline: boolean | Partial<PromoOutlineConfig>,
    overlayLayer: number | null = null
  ): void {
    const renderer = this.renderer!;
    const scene = this.scene!;
    const camera = this.camera!;

    if (outline === false) {
      renderer.render(scene, camera);
      if (overlayLayer != null) {
        const prevAutoClear = renderer.autoClear;
        renderer.autoClear = false;
        camera.layers.set(overlayLayer);
        renderer.render(scene, camera);
        camera.layers.set(0);
        renderer.autoClear = prevAutoClear;
      }
      return;
    }

    if (!this.outline) {
      this.outline = setupOutlinePipeline(
        renderer,
        scene,
        camera,
        this.width,
        this.height
      );
    }
    applyOutlineConfig(this.outline, typeof outline === "object" ? outline : {});
    renderOutlineFrame(
      this.outline,
      renderer,
      scene,
      camera,
      overlayLayer ?? undefined
    );
  }

  private toBlob(
    options: SkinSnapshotOptions,
    canvasOverride?: HTMLCanvasElement | null
  ): Promise<Blob> {
    const canvas = canvasOverride ?? this.renderer!.domElement;
    const mimeType = options.mimeType ?? "image/webp";
    const quality = options.quality ?? 0.9;

    return new Promise((resolve, reject) => {
      canvas.toBlob(
        (blob) => {
          if (blob) resolve(blob);
          else reject(new Error("Failed to read the rendered canvas"));
        },
        mimeType,
        quality
      );
    });
  }
}
